      grid-template-columns: repeat(3, 1fr);
      gap: 2rem;
      max-width: 900px;
      margin: 0 auto;
    }
    .stat-card {
      display: flex;
      flex-direction: column;
      align-items: center;
      text-align: center;
    }
    .stat-circle {
      position: relative;
      width: 160px;
      height: 160px;
      margin-bottom: 1.25rem;
    }
    .stat-circle svg {
      transform: rotate(-90deg);
      width: 100%;
      height: 100%;
    }
    .stat-circle-bg {
      fill: none;
      stroke: rgba(255,255,255,0.05);
      stroke-width: 8;
    }
    .stat-circle-fill {
      fill: none;
      stroke: var(--teal);
      stroke-width: 8;
      stroke-linecap: round;
      stroke-dasharray: 440;
      stroke-dashoffset: 440;
      transition: stroke-dashoffset 1.5s ease-out;
