    .timeline-item {
      display: grid;
      grid-template-columns: 140px 1fr;
      gap: 1.5rem;
      align-items: center;
    }
    .timeline-label {
      text-align: right;
    }
    .timeline-label strong {
      display: block;
      font-size: 1.3rem;
      font-weight: 800;
      color: var(--teal);
    }
    .timeline-label span {
