    .timeline-item:nth-child(3) .timeline-bar { background: linear-gradient(90deg, var(--navy), #1a3066); border: 1px solid rgba(0,180,216,0.3); }

    /* Accordion Features */
    .accordion-section { padding: 80px 2rem; background: linear-gradient(180deg, var(--bg-dark) 0%, #0a1520 100%); }
    .accordion-list {
