      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 1rem;
    }
    .footer-bottom p { color: var(--gray-500); font-size: 0.8rem; }
    .footer-portals { display: flex; gap: 1rem; }
    .footer-portals a { font-size: 0.8rem; color: var(--gray-500); transition: color 0.15s; }
    .footer-portals a:hover { color: var(--teal); }

    @media (max-width: 1024px) {
      .benefits-grid { grid-template-columns: repeat(3, 1fr); }
    }
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .mobile-toggle { display: block; }
      .nav-cta { display: none; }
      .benefits-grid { grid-template-columns: repeat(2, 1fr); }
      .stats-grid { grid-template-columns: 1fr; gap: 3rem; }
      .timeline-item { grid-template-columns: 1fr; gap: 0.5rem; }
      .timeline-label { text-align: left; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 480px) {
      .benefits-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr; }
    }
  </style>
</head>
