<script>
  // Accordion
  function toggleAccordion(header) {
    const item = header.parentElement;
    const body = item.querySelector('.accordion-body');
    const isOpen = item.classList.contains('open');

    document.querySelectorAll('.accordion-item').forEach(i => {
      i.classList.remove('open');
      i.querySelector('.accordion-body').style.maxHeight = '0';
    });

    if (!isOpen) {
      item.classList.add('open');
      body.style.maxHeight = body.scrollHeight + 'px';
    }
  }

  // Testimonial carousel
  let currentTestimonial = 0;
  const totalTestimonials = 3;

  function moveTestimonial(dir) {
    currentTestimonial = (currentTestimonial + dir + totalTestimonials) % totalTestimonials;
    updateTestimonial();
  }

  function updateTestimonial() {
    const track = document.getElementById('testimonialTrack');
    track.style.transform = `translateX(-${currentTestimonial * 100}%)`;
    document.querySelectorAll('.testimonial-dot').forEach((dot, i) => {
      dot.classList.toggle('active', i === currentTestimonial);
    });
  }

  document.querySelectorAll('.testimonial-dot').forEach(dot => {
    dot.addEventListener('click', () => {
      currentTestimonial = parseInt(dot.dataset.index);
      updateTestimonial();
    });
  });

  // Animate stats on scroll
  const statObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.querySelectorAll('.stat-circle-fill').forEach(circle => {
          const pct = parseInt(circle.dataset.pct);
          const offset = 440 - (440 * pct / 100);
          circle.style.strokeDashoffset = offset;
        });
        statObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });

  document.querySelectorAll('.stats-grid').forEach(el => statObserver.observe(el));

  // Animate timeline bars on scroll
  const timelineObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.querySelectorAll('.timeline-bar').forEach(bar => {
          bar.style.width = bar.dataset.width + '%';
        });
        timelineObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });

  document.querySelectorAll('.timeline-list').forEach(el => timelineObserver.observe(el));
</script>
