<script>
  const form = document.getElementById('demoForm');
  const submitBtn = document.getElementById('submitBtn');
  const formSuccess = document.getElementById('formSuccess');

  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  function validateField(field) {
    const group = field.closest('.form-group');
    const name = field.name;
    const value = field.value.trim();

    group.classList.remove('error');

    if (!value) {
      if (name === 'phone' || name === 'comments') return true; // optional
      group.classList.add('error');
      return false;
    }

    if (name === 'email') {
      if (!EMAIL_RE.test(value)) {
        group.classList.add('error');
        return false;
      }
      // reject common free email providers
      const freeEmails = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'aol.com'];
      const domain = value.split('@')[1]?.toLowerCase();
      if (freeEmails.includes(domain)) {
        group.classList.add('error');
        return false;
      }
    }

    return true;
  }

  // Live validation on blur
  form.querySelectorAll('input, select, textarea').forEach(field => {
    field.addEventListener('blur', () => validateField(field));
    field.addEventListener('input', () => {
      field.closest('.form-group').classList.remove('error');
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const requiredFields = form.querySelectorAll('[name]:not([name="phone"]):not([name="comments"])');
    let isValid = true;

    requiredFields.forEach(field => {
      if (!validateField(field)) isValid = false;
    });

    if (!isValid) return;

    submitBtn.disabled = true;
    submitBtn.textContent = 'Submitting...';

    // Simulate network request
    setTimeout(() => {
      form.style.display = 'none';
      formSuccess.classList.add('show');
    }, 1200);
  });
</script>
